// Checkout handler with paidEvent logging fix
const { logPaidEvent } = require('./revenueTracker');

async function handleCheckout(req, res) {
  try {
    const { userId, plan, amount, currency } = req.body;
    // ... existing validation and payment processing ...

    // On successful payment:
    await logPaidEvent({ userId, plan, amount, currency });

    res.status(200).json({ success: true });
  } catch (err) {
    console.error('Checkout error:', err);
    res.status(500).json({ error: 'Checkout failed' });
  }
}

module.exports = { handleCheckout };
